-- ============================================================================
-- V202608140000__init_menu_and_role_menu.sql
-- 待决项 F-1 的落地：sys_menu 菜单/按钮数据 + sys_role_menu 内置角色绑定
--
-- 【为什么是增量脚本而不是改基线】
--   docs/sql/edumatrix_ddl.sql 是 Flyway 初始基线 V202608120000__baseline.sql，
--   契约 §7.3 规定「该文件此后不再随手改动，否则新老环境会分叉」。本文件一个字未动。
--
-- 【平台级行（契约 §2.9）】
--   sys_menu 无 tenant_id 列（平台级表，不进租户插件）；
--   sys_role_menu 的 tenant_id 一律写 0，租户插件注入条件必须是
--   (tenant_id = ? OR tenant_id = 0)，否则非超管用户 perms 恒为空数组。
--   这四个内置角色的绑定对 org_admin 全只读：仅 super_admin 可改，任何人不可删。
--
-- 【parent_id 约定】DDL 注释：父菜单ID（0=顶级）。
--   顶级项一律 parent_id = 0，包括不挂在任何主导航目录下的顶级菜单
--   （工作台 A2 / 导师看板 B1，PRD §6 的入口列均为「登录后默认」）。
--   parent_id 绝不可等于自身 id——按 idx_parent_id(parent_id, sort) 取子节点时，
--   自环行会把自己查成自己的子节点：递归 CTE 因成环报错或无限展开，
--   「按 parent 分组再拼树」则因找不到 parent_id=0 的入口而让它从树上消失，
--   而 perms 又确实返回了。这是一个「接口 200、数据齐全、界面不对」的静默故障。
--
-- 【ID 规则】固定值，不用雪花算法（初始化数据必须可重复、可对账）：
--   id = 1949000000000000000 + 目录号*10000 + 菜单号*100 + 按钮号
--   末五位即 (目录, 菜单, 按钮)，肉眼可读、可 diff、可反查。
--
-- 节点 124 行（目录 7 / 菜单 29 / 按钮 88）；
-- 角色绑定 201 行。菜单树权威表见 DESIGN-CONTRACT.md 附表 A。
-- ============================================================================

SET NAMES utf8mb4;

DELETE FROM `sys_role_menu` WHERE `tenant_id` = 0;
DELETE FROM `sys_menu` WHERE `id` BETWEEN 1949000000000000000 AND 1949000000000999999;


